/**
 * Download demo of the fixture site (http://localhost:5180/download): real,
 * playable streams (synthetic media generated by the bundled FFmpeg, see
 * media/synthetic-media.ts) served from localhost with latency, so the Queue
 * tab's progress, cancel, retry, error messages and FFmpeg's analysis of the
 * downloaded media can be watched in Chrome.
 *
 * Shared by scripts/fixture-server.ts and tests/integration/download-fixtures.test.ts.
 */
import type { FixtureResponse } from './fixture-routes.ts';
import { dashManifest, hlsMasterPlaylist, hlsMediaPlaylist } from './media/synthetic-manifests.ts';
import type { Rendition, SyntheticMedia, SyntheticOptions } from './media/synthetic-media.ts';

/** Media the demo serves: 8 minutes of 4-second segments in two qualities. */
export const DEMO_MEDIA: SyntheticOptions = {
  segmentSeconds: 4,
  segments: 120,
  fps: 10,
  video: [
    { name: 'v360', width: 640, height: 360 },
    { name: 'v180', width: 320, height: 180 },
  ],
};

export interface DownloadDemoOptions {
  /** Delay before each segment response. */
  latencyMs?: number;
}

export interface DemoRequest {
  referer?: string | undefined;
  /** The Range header (progressive files, 0.3.0). */
  range?: string | undefined;
}

export interface DemoStream {
  path: string;
  title: string;
  tryThis: string;
}

/** Manifests the download page loads, as a player would. */
export const DOWNLOAD_STREAMS: readonly DemoStream[] = [
  {
    path: '/download/plain/plain.m3u8',
    title: 'HLS · MPEG-TS · 360p / 180p · English audio',
    tryThis: 'Download it and watch the progress, then FFmpeg checking the media; cancel one run halfway, then retry it.',
  },
  {
    path: '/download/dash/movie.mpd',
    title: 'DASH · fragmented MP4 · 360p / 180p · English audio',
    tryThis: 'Same as above for DASH (each track starts with an init segment).',
  },
  {
    path: '/download/flaky/flaky.m3u8',
    title: 'HLS · every 10th segment fails once (HTTP 503)',
    tryThis: 'Completes anyway; the Queue tab counts the retries.',
  },
  {
    path: '/download/protected/protected.m3u8',
    title: 'HLS · answers 403 without this page as Referer',
    tryThis: 'Completes only if the extension replays the page’s Referer (DNR rule) on every segment.',
  },
  {
    path: '/download/expiring/expiring.m3u8',
    title: 'HLS · link "expires" a third of the way in (HTTP 403)',
    tryThis: 'Fails with the expired-link message after two manifest refreshes.',
  },
];

const HLS = 'application/vnd.apple.mpegurl';
const KINDS = new Set(['plain', 'flaky', 'protected', 'expiring']);
const AUDIO_ID = 'audio-en';

/** True when the request comes from (or replays the Referer of) the download page. */
function fromDownloadPage(referer: string | undefined): boolean {
  if (referer === undefined) return false;
  try {
    const url = new URL(referer);
    return ['localhost', '127.0.0.1'].includes(url.hostname) && url.pathname.startsWith('/download');
  } catch {
    return false;
  }
}

/** Routes below /download/ for this media. Undefined for paths it does not know (the caller answers 404). */
export function createDownloadRouter(
  media: SyntheticMedia,
  options: DownloadDemoOptions = {},
): (pathname: string, request?: DemoRequest) => FixtureResponse | undefined {
  const latencyMs = options.latencyMs ?? 250;
  const videos = media.options.video;
  const segments = media.options.segments;
  const expireAfter = Math.floor(segments / 3);
  /** Requests per flaky segment: odd attempts fail, so every download sees one failure per such segment. */
  const flakyHits = new Map<string, number>();

  const ok = (contentType: string, body: string | Uint8Array<ArrayBuffer>, delayMs = 0): FixtureResponse => ({ status: 200, contentType, body, delayMs });
  const error = (status: number, delayMs = latencyMs): FixtureResponse => ({ status, contentType: 'text/plain', body: `HTTP ${status}`, delayMs });

  const master = hlsMasterPlaylist(
    videos.map((video) => ({ uri: `${video.name}/index.m3u8`, width: video.width, height: video.height, rendition: media.ts.video[video.name] as Rendition })),
    { uri: 'audio/index.m3u8', name: 'English', language: 'en', rendition: media.ts.audio },
  );
  const mpd = dashManifest(
    videos.map((video) => ({ id: video.name, width: video.width, height: video.height, rendition: media.fmp4.video[video.name] as Rendition })),
    { id: AUDIO_ID, language: 'en', rendition: media.fmp4.audio },
  );
  const tsRendition = (name: string): Rendition | undefined => (name === 'audio' ? media.ts.audio : media.ts.video[name]);
  const dashRendition = (id: string): Rendition | undefined => (id === AUDIO_ID ? media.fmp4.audio : media.fmp4.video[id]);

  return (pathname, request = {}) => {
    const dash = /^\/download\/dash\/(?:(movie\.mpd)|([\w-]+)\/(?:(init\.mp4)|seg-(\d+)\.m4s))$/.exec(pathname);
    if (dash) {
      if (dash[1]) return ok('application/dash+xml', mpd);
      const rendition = dashRendition(dash[2] ?? '');
      if (!rendition) return undefined;
      if (dash[3]) return rendition.init ? ok('video/mp4', rendition.init, latencyMs) : undefined;
      const body = rendition.segments[Number(dash[4]) - 1]; // $Number$ starts at 1
      return body ? ok('video/mp4', body, latencyMs) : undefined;
    }

    const hls = /^\/download\/(\w+)\/(?:(\w+)\.m3u8|(\w+)\/(?:(index\.m3u8)|seg-(\d+)\.ts))$/.exec(pathname);
    const kind = hls?.[1];
    if (!hls || kind === undefined || !KINDS.has(kind)) return undefined;
    if (kind === 'protected' && !fromDownloadPage(request.referer)) return error(403, 0);
    if (hls[2] !== undefined) return hls[2] === kind ? ok(HLS, master) : undefined;
    const rendition = tsRendition(hls[3] ?? '');
    if (!rendition) return undefined;
    if (hls[4] !== undefined) return ok(HLS, hlsMediaPlaylist(rendition));

    const index = Number(hls[5]);
    const body = rendition.segments[index];
    if (!body) return undefined;
    if (kind === 'expiring' && index >= expireAfter) return error(403);
    if (kind === 'flaky' && index % 10 === 5) {
      const hits = (flakyHits.get(pathname) ?? 0) + 1;
      flakyHits.set(pathname, hits);
      if (hits % 2 === 1) return error(503);
    }
    return ok('video/mp2t', body, latencyMs);
  };
}
